const crypto = require('crypto');

// Optional text input (paste/chat)
const rawText = ($input.item.json.quote_text_raw || '').toString().trim();

// Optional hints
const zip = ($input.item.json.zip || '').toString().trim();
const trade = ($input.item.json.trade || '').toString().trim();
const lat = ($input.item.json.lat || '').toString().trim();
const lng = ($input.item.json.lng || '').toString().trim();

const analysis_id = crypto.randomBytes(12).toString('hex');

// If user provided text, no file is required
if (rawText) {
  return [{
    json: {
      analysis_id,
      filename: 'pasted-text',
      mime: 'text/plain',
      inputs: { zip, trade, lat, lng },
      quote_text: rawText,
      image_data_url: ''
    }
  }];
}

// Otherwise expect a binary upload named "file"
const bin = $input.item.binary?.file;
if (!bin) {
  throw new Error('No quote_text_raw provided and no binary file found. Expected multipart field name "file" or JSON field "quote_text_raw".');
}

const mime = bin.mimeType || 'application/octet-stream';
const filename = bin.fileName || 'upload';

let image_data_url = '';
if (mime.startsWith('image/')) {
  image_data_url = `data:${mime};base64,${bin.data}`;
}

let quote_text = '';
if (mime === 'application/pdf') {
  // Self-hosted recommended: requires pdf-parse module.
  // If you are on n8n Cloud, replace this with a PDF extraction service.
  const pdfParse = require('pdf-parse');
  const buf = Buffer.from(bin.data, 'base64');
  const parsed = await pdfParse(buf);
  quote_text = (parsed.text || '').trim();
}

return [{
  json: {
    analysis_id,
    filename,
    mime,
    inputs: { zip, trade, lat, lng },
    quote_text,
    image_data_url
  }
}];

