function pickText(resp) {
  const out = resp?.body?.output || resp?.output;
  if (!Array.isArray(out)) return '';
  for (const item of out) {
    const content = item?.content;
    if (!Array.isArray(content)) continue;
    for (const c of content) {
      if ((c?.type === 'output_text' || c?.type === 'text') && typeof c?.text === 'string') return c.text;
    }
  }
  return '';
}

const raw = $input.item.json;
const text = pickText(raw);
if (!text) throw new Error('No text returned from OpenAI Responses API.');

let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start === -1 || end === -1) throw e;
  parsed = JSON.parse(text.slice(start, end + 1));
}

return [{ json: parsed }];
